from decimal import Decimal, ROUND_HALF_UP
orders = await orders_get_orders()
ids = [o["order_id"] for o in orders]
regions_raw = sorted({repr(o["region"]) for o in orders})
statuses = sorted({repr(o["status"]) for o in orders})
bad = []
totals = {}
for o in orders:
    try:
        amt = Decimal(str(o["amount"]).strip())
    except Exception:
        bad.append(o["order_id"]); continue
    r = str(o["region"]).strip().lower()
    totals[r] = totals.get(r, Decimal("0")) + amt
lines = [f"{r},{t.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}" for r, t in sorted(totals.items())]
return {"n": len(orders), "unique_ids": len(set(ids)), "regions_raw": regions_raw, "statuses": statuses, "bad_amounts": bad, "lines": lines}

